WHERE 1=1
AND c.owner_id IS NOT NULL



AND t.customer_id=#{customerId}
AND t.status=#{status}
AND (t.contact_name LIKE CONCAT('%',#{keyword},'%') OR c.company_name LIKE CONCAT('%',#{keyword},'%') OR t.phone LIKE CONCAT('%',#{keyword},'%') OR t.landline LIKE CONCAT('%',#{keyword},'%') OR t.wechat LIKE CONCAT('%',#{keyword},'%') OR t.email LIKE CONCAT('%',#{keyword},'%') OR t.job_title LIKE CONCAT('%',#{keyword},'%'))
